    const a=wl[k]/sl,b=wt[k]/st,d=[0,1,2].map(i=>(ang[0][i]*a+ang[1][i]*b)*D);
    const Rh=mmul(R,rotM(d[0]/2,d[1]/2,d[2]/2)),v=mv(Rh,[0,dy,0]);
